import csv

# Build a map: point_uri -> timeseries_id for Electric_Power_Sensor equipment only
equipment_sensors = {}
with open(CATALOG_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['point_class'] == 'Electric_Power_Sensor':
            equipment_sensors[row['point_uri']] = row['timeseries_id']

print(f"Found {len(equipment_sensors)} Electric_Power_Sensor entries in catalog")
for uri, ts_id in equipment_sensors.items():
    print(f"  {uri} -> {ts_id}")

# Now read values at 2018-10-25 11:00
target_ts = "2018-10-25 11:00"
values = {}
with open(VALUES_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['timeseries_id'] in equipment_sensors.values() and row['timestamp'] == target_ts:
            values[row['timeseries_id']] = float(row['value'])

print(f"\nValues at {target_ts}:")
# Map back to equipment URI
ts_to_uri = {v: k for k, v in equipment_sensors.items()}
for ts_id, val in sorted(values.items(), key=lambda x: -x[1]):
    print(f"  {ts_to_uri[ts_id]}: {val} W")
